  "evaluated_rules": [
    {
      "rule_id": "HWG-STAMM-02",
      "status": "VIOLATION",
      "affected_elements": ["tfEmail"],
      "finding": "Das E-Mail-Feld trägt das Label 'HWGLU-Email'. HWGLU ist eine interne Organisationsabkürzung (Hochschule für Wirtschaft und Gesellschaft Ludwigshafen) und entspricht keiner der kanonischen Bezeichnungen ('E-Mail-Adresse', 'E-Mail', 'Hochschul-E-Mail'). Es handelt sich um einen technischen/organisatorischen Kürzel-Bezeichner, der als sichtbares Label verwendet wird – ein explizit genanntes Anti-Pattern der Regel.",
      "remediation_suggestion": "Label des Felds tfEmail auf 'E-Mail-Adresse' oder 'Hochschul-E-Mail' umstellen. Falls die Abgrenzung zur privaten E-Mail nötig ist, den Hilfetext nutzen, um den Kontext zu erklären, statt die Abkürzung im Label zu belassen."
    },
    {
      "rule_id": "HWG-UI-01",
      "status": "VIOLATION",
      "affected_elements": ["txtDevNote"],
      "finding": "Das XSpan-Element txtDevNote enthält den Text 'Fieldset wird per JavaScript eingeblendet, wenn Shibboleth/LDAP-Member authentifiziert.' Dies ist eine interne Entwickler-/Konfigurationsnotiz, die die technische Implementierung (JavaScript, Shibboleth, LDAP) beschreibt. Sie richtet sich nicht an Antragstellende, sondern dokumentiert das Verhalten des Formulars für Entwickler. Sie ist im Frontend sichtbar und verstößt gegen die Anforderung, keine Code-Artefakte oder Arbeitsnotizen im sichtbaren UI zu belassen.",
      "remediation_suggestion": "Das Element txtDevNote aus dem sichtbaren Formular entfernen oder in einen nicht sichtbaren Kommentar (XComment) bzw. in die Formcycle-Dokumentation verlagern. Sichtbare Hinweise an Antragstellende sollten ausschließlich deren Aufgabe betreffen."
    },
    {
      "rule_id": "HWG-BTN-01",
      "status": "VIOLATION",
      "affected_elements": ["btnSubmit", "btnKritisch"],
      "finding": "btnSubmit trägt das Label 'senden' – ein generisches, kontextloses Minimal-Verb ohne Zielobjekt (analog zum disallowten Muster 'Abschicken'). btnKritisch trägt das Label 'Kritischer Fall' – eine reine Substantiv-/Statusbezeichnung ohne Handlungsverb (analog zum disallowten Muster 'Eilfall'). Beide erfüllen das geforderte Muster [Zielobjekt] + [Vollverb im Infinitiv] nicht.",
      "remediation_suggestion": "btnSubmit: Label auf z. B. 'Antrag einreichen' oder 'Sondergenehmigung beantragen' ändern. btnKritisch: Label auf eine handlungsorientierte Formulierung umstellen, z. B. 'Kritischen Fall melden' oder 'Eilfall-Antrag absenden'."
    },
    {
      "rule_id": "HWG-UX-02",
      "status": "NOT_APPLICABLE",
      "affected_elements": [],
      "finding": "Die Komplexitätsschwelle ist nicht erreicht (1 Seite, 8 Eingabefelder; Schwellenwert: ≥ 3 Seiten oder ≥ 25 Felder). Die Empfehlung zum Zwischenspeichern mit Fortsetzungs-Link greift daher nicht.",
      "remediation_suggestion": "Keine Maßnahme erforderlich. Bei zukünftiger Erweiterung des Formulars auf ≥ 3 Seiten oder ≥ 25 Eingabefelder eine 'Zwischenspeichern'-Schaltfläche (Aktion 'speichern') und einen FC_EMAIL-Versand mit [%$FORM_PROCESS_LINK%] an die antragstellende Person ergänzen."
    },
    {
      "rule_id": "HWG-LANG-01",
      "status": "VIOLATION",
      "affected_elements": ["tfEmail", "tfKostenstelle"],
      "finding": "Das Label 'HWGLU-Email' verwendet die interne Organisationsabkürzung HWGLU ohne jeglichen Hilfetext; Antragstellende, die die Abkürzung nicht kennen, können den Bezug zur Hochschule nicht herstellen. Das Feld 'Kostenstelle' (tfKostenstelle) ist ein hochschulinterner Verwaltungsbegriff (Haushalts-/Vergabeterminologie) ohne zugehörigen Hilfetext, der z. B. erklärt, wo die Kostenstelle zu finden ist oder was sie bedeutet. Beide Begriffe sind außerhalb des Headers und nicht erläutert.",
      "remediation_suggestion": "Für tfEmail: Label auf 'E-Mail-Adresse' ändern und ggf. im Hilfetext den Kontext (z. B. 'Bitte Ihre Hochschul-E-Mail-Adresse angeben') erklären. Für tfKostenstelle: Hilfetext ergänzen, z. B. 'Die Kostenstelle finden Sie auf Ihrem Dienstplan oder im Finanzportal der HWG. Sie besteht aus einer 8-stelligen Ziffernfolge.'"
    },
    {
      "rule_id": "HWG-LANG-02",
      "status": "PASS",
      "affected_elements": [],
